/// url = 'http://octofhir.com/ccda-fhir/StructureMap/fhir-to-ccda'
/// name = 'FhirToCcda'
/// title = 'FHIR R4 document Bundle to a C-CDA document'
/// status = 'active'
/// description = 'A FHIR document Bundle to a C-CDA document (US Realm Header, C-CDA 5.0.0 templates): the Composition to the header and sections, the resources its sections refer to to entries.'

map "http://octofhir.com/ccda-fhir/StructureMap/fhir-to-ccda" = "FhirToCcda"

uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as source
uses "http://hl7.org/fhir/StructureDefinition/Composition" alias Composition as source
uses "http://hl7.org/fhir/StructureDefinition/Reference" alias Reference as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as target

imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-datatypes-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-participants-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-patient-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-allergies-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-problems-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-medications-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-immunizations-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-results-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-procedures-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-encounters-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-social-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-notes-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-plans-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-status-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-family-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-devices-to-cda"

group Document(source bundle : Bundle, target cda : ClinicalDocument) {
  bundle.entry first as entry then {
    entry.resource : Composition as composition then Header(composition, bundle, cda);
  };
}

// The US Realm Header; a summary of episode (LOINC 34133-9) is also a CCD.
group Header(source composition : Composition, source bundle : Bundle, target cda : ClinicalDocument) {
  composition -> cda.realmCode as realm, realm.code = 'US';
  composition -> cda.typeId as typeId, typeId.root = '2.16.840.1.113883.1.3', typeId.extension = 'POCD_HD000040';
  composition -> cda.templateId as template, template.root = '2.16.840.1.113883.10.20.22.1.1', template.extension = '2024-05-01';
  composition where (type.coding.where(system = 'http://loinc.org' and code = '34133-9').exists()) -> cda.templateId as template, template.root = '2.16.840.1.113883.10.20.22.1.2', template.extension = '2024-05-01';
  composition.identifier as identifier -> cda.id as id then IdentifierToII(identifier, id);
  composition where (identifier.empty()) then {
    bundle.identifier as identifier -> cda.id as id then IdentifierToII(identifier, id);
  };
  composition where (identifier.empty() and %bundle.identifier.empty()) -> uuid() as u, cda.id as id, id.root = evaluate(u, $this.upper());
  composition.type as type -> cda.code = create('CE') as code then CodeableConceptToCD(type, code);
  composition.title as title -> cda.title as t, t.xmlText = title;
  composition.date as date -> cda.effectiveTime as time then DateTimeToTS(date, time);
  composition.confidentiality as confidentiality -> cda.confidentialityCode as code, code.code = confidentiality, code.codeSystem = '2.16.840.1.113883.5.25';
  composition where (confidentiality.empty()) -> cda.confidentialityCode as code, code.code = 'N', code.codeSystem = '2.16.840.1.113883.5.25';
  composition.language as language -> cda.languageCode as code, code.code = language;
  composition where (language.empty()) -> cda.languageCode as code, code.code = 'en-US';
  composition.subject as subject then {
    bundle.entry as entry where (fullUrl = %subject.reference) then {
      entry.resource : Patient as patient -> cda.recordTarget as target, target.patientRole as role then PatientToPatientRole(patient, role, bundle);
    };
  };
  composition.author as author then {
    bundle.entry as entry where (fullUrl = %author.reference) then {
      entry.resource as resource -> cda.author as cdaAuthor then Author(resource, composition, bundle, cdaAuthor);
    };
  };
  composition.custodian as custodian then {
    bundle.entry as entry where (fullUrl = %custodian.reference) then {
      entry.resource : Organization as organization -> cda.custodian as c, c.assignedCustodian as assigned, assigned.representedCustodianOrganization as org then OrganizationToCustodian(organization, org);
    };
  };
  // Composition.event: documentationOf/serviceEvent (a CCD needs one, with a period).
  composition.event as event -> cda.documentationOf as documentation, documentation.serviceEvent as service, service.classCode = 'PCPR' then {
    event.code first as code -> service.code = create('CE') as c then CodeableConceptToCD(code, c);
    event.period as period -> service.effectiveTime as time then {
      period then PeriodToIVLTS(period, time);
      period where (end.empty()) -> time.high as high, high.nullFlavor = 'UNK';
    };
    event where (period.empty()) -> service.effectiveTime as time, time.low as low, low.nullFlavor = 'UNK';
    event.detail as ref then ReferenceToPerformer(ref, bundle, service);
  };
  composition where (event.empty() and type.coding.where(system = 'http://loinc.org' and code = '34133-9').exists()) -> cda.documentationOf as documentation, documentation.serviceEvent as service, service.classCode = 'PCPR', service.effectiveTime as time, time.low as low, low.nullFlavor = 'UNK', time.high as high, high.nullFlavor = 'UNK';
  composition.attester as attester where (mode = 'legal') then {
    attester.party as party then {
      bundle.entry as entry where (fullUrl = %party.reference) then {
        entry.resource : Practitioner as practitioner -> cda.legalAuthenticator as authenticator, authenticator.signatureCode as signature, signature.code = 'S', authenticator.assignedEntity as entity then {
          attester.time as time -> authenticator.time as t then DateTimeToTS(time, t);
          attester where (time.empty()) then {
            composition.date as date -> authenticator.time as t then DateTimeToTS(date, t);
          };
          practitioner then PractitionerToAssignedEntity(practitioner, entity);
        };
        entry.resource : PractitionerRole as role -> cda.legalAuthenticator as authenticator, authenticator.signatureCode as signature, signature.code = 'S', authenticator.assignedEntity as entity then {
          attester.time as time -> authenticator.time as t then DateTimeToTS(time, t);
          attester where (time.empty()) then {
            composition.date as date -> authenticator.time as t then DateTimeToTS(date, t);
          };
          role then RoleToAssignedEntity(role, bundle, entity);
        };
      };
    };
  };
  // The encounter the document is about: componentOf/encompassingEncounter.
  composition.encounter as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Encounter as encounter -> cda.componentOf as componentOf, componentOf.encompassingEncounter as encompassing then EncounterToEncompassing(encounter, bundle, encompassing);
    };
  };
  composition -> cda.component as component, component.structuredBody as body then {
    composition.section as section -> body.component as sectionComponent, sectionComponent.section as cdaSection then Section(section, bundle, cdaSection);
    // Birth sex, sex, gender identity, tribal affiliation are Social History entries in C-CDA:
    // a section of their own when the Composition has no Social History section.
    composition where (section.code.coding.where(system = 'http://loinc.org' and code = '29762-2').empty()) then {
      composition.subject as subject then {
        bundle.entry as entry where (fullUrl = %subject.reference) then {
          entry.resource : Patient as patient where (extension.where(url in ('http://hl7.org/fhir/us/core/StructureDefinition/us-core-birthsex' | 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-sex' | 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-genderIdentity' | 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-tribal-affiliation')).exists()) -> body.component as sectionComponent, sectionComponent.section as cdaSection then SocialSectionFromPatient(patient, cdaSection);
        };
      };
    };
  };
}

// An author: a Practitioner or a Device, at the time of the document.
group Author(source resource, source composition : Composition, source bundle : Bundle, target author : Author) {
  composition.date as date -> author.time as time then DateTimeToTS(date, time);
  resource : Practitioner as practitioner -> author.assignedAuthor as assigned then PractitionerToAssignedAuthor(practitioner, assigned);
  resource : PractitionerRole as role -> author.assignedAuthor as assigned then RoleToAssignedAuthor(role, bundle, assigned);
  resource : Device as device -> author.assignedAuthor as assigned then DeviceToAssignedAuthor(device, bundle, assigned);
  resource : Organization as organization -> author.assignedAuthor as assigned, assigned.id as id, id.nullFlavor = 'NA', assigned.representedOrganization as org then OrganizationToOrganization(organization, org);
}

// A section: its template by its LOINC code (the C-CDA 5.0.0 section templates), title, code,
// narrative, and the entries of the kinds the maps know, by resource type.
group Section(source section, source bundle : Bundle, target cdaSection : Section) {
  section.code as code then {
    code.coding as coding where (system = 'http://loinc.org') then {
      coding.code as c where (c = '48765-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.6.1', template.extension = '2015-08-01';
      coding.code as c where (c = '11450-4') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.5.1', template.extension = '2015-08-01';
      coding.code as c where (c = '75310-3') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.58', template.extension = '2015-08-01';
      coding.code as c where (c = '42346-7') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.44', template.extension = '2015-08-01';
      coding.code as c where (c = '42349-1') -> cdaSection.templateId as template, template.root = '1.3.6.1.4.1.19376.1.5.3.1.3.1', template.extension = '2014-06-09';
      coding.code as c where (c = '51848-0') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.8';
      coding.code as c where (c = '51847-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.9', template.extension = '2014-06-09';
      coding.code as c where (c = '46241-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.43', template.extension = '2015-08-01';
      coding.code as c where (c = '11535-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.24', template.extension = '2015-08-01';
      coding.code as c where (c = '46264-8') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.23', template.extension = '2014-06-09';
      coding.code as c where (c = '10157-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.15', template.extension = '2015-08-01';
      coding.code as c where (c = '47420-5') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.14', template.extension = '2014-06-09';
      coding.code as c where (c = '10190-7') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.56', template.extension = '2015-08-01';
      coding.code as c where (c = '18776-5') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.10', template.extension = '2014-06-09';
      coding.code as c where (c = '61146-7') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.60';
      coding.code as c where (c = '10183-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.11.1', template.extension = '2015-08-01';
      coding.code as c where (c = '10160-0') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.1.1', template.extension = '2014-06-09';
      coding.code as c where (c = '11369-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.2.1', template.extension = '2015-08-01';
      coding.code as c where (c = '30954-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.3.1', template.extension = '2015-08-01';
      coding.code as c where (c = '8716-3') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.4.1', template.extension = '2015-08-01';
      coding.code as c where (c = '47519-4') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.7.1', template.extension = '2014-06-09';
      // Narrative-only sections (8648-8 is both Hospital Course and Course of Care: left without one).
      coding.code as c where (c = '10154-3') -> cdaSection.templateId as template, template.root = '1.3.6.1.4.1.19376.1.5.3.1.1.13.2.1';
      coding.code as c where (c = '46239-0') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.13';
      coding.code as c where (c = '10210-3') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.2.5';
      coding.code as c where (c = '10164-2') -> cdaSection.templateId as template, template.root = '1.3.6.1.4.1.19376.1.5.3.1.3.4';
      coding.code as c where (c = '18841-7') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.42';
      coding.code as c where (c = '8653-8') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.41';
      coding.code as c where (c = '10184-0') -> cdaSection.templateId as template, template.root = '1.3.6.1.4.1.19376.1.5.3.1.3.26';
      coding.code as c where (c = '11493-4') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.16';
      coding.code as c where (c = '11329-0') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.39';
      coding.code as c where (c = '61149-1') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.21.2.1';
      coding.code as c where (c = '10216-0') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.7.12';
      coding.code as c where (c = '10223-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.7.14';
      coding.code as c where (c = '10218-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.35';
      coding.code as c where (c = '29554-3') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.27';
      coding.code as c where (c = '59775-7') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.18.2.12';
      coding.code as c where (c = '59770-8') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.18.2.9';
      coding.code as c where (c = '59771-6') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.40';
      coding.code as c where (c = '59773-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.31';
      coding.code as c where (c = '29299-5') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.12';
      coding.code as c where (c = '10187-3') -> cdaSection.templateId as template, template.root = '1.3.6.1.4.1.19376.1.5.3.1.3.18';
      coding.code as c where (c = '61150-9') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.21.2.2';
      coding.code as c where (c = '11537-8') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.7.13';
      coding.code as c where (c = '29762-2') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.17', template.extension = '2015-08-01';
      coding.code as c where (c = '46240-8') -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.22.1', template.extension = '2015-08-01';
    };
  };
  // A section of notes only: the Notes Section.
  section where (entry.exists() and entry.reference.all($this in %bundle.entry.where(resource is DocumentReference).fullUrl)) -> cdaSection.templateId as template, template.root = '2.16.840.1.113883.10.20.22.2.65', template.extension = '2026-05-01';
  section.code as sectionCode -> cdaSection.code = create('CE') as c then {
    sectionCode then CodeableConceptToCD(sectionCode, c);
    // The Discharge Medications section's code carries the 75311-1 translation.
    sectionCode where (coding.where(system = 'http://loinc.org' and code = '10183-2').exists() and coding.where(system = 'http://loinc.org' and code = '75311-1').empty()) -> c.translation as translation, translation.code = '75311-1', translation.codeSystem = '2.16.840.1.113883.6.1', translation.displayName = 'Discharge medications';
    sectionCode where (coding.where(system = 'http://loinc.org' and code = '46241-6').exists() and coding.where(system = 'http://loinc.org' and code = '42347-5').empty()) -> c.translation as translation, translation.code = '42347-5', translation.codeSystem = '2.16.840.1.113883.6.1', translation.displayName = 'Admission diagnosis (narrative)';
    sectionCode where (coding.where(system = 'http://loinc.org' and code = '11535-2').exists() and coding.where(system = 'http://loinc.org' and code = '78375-3').empty()) -> c.translation as translation, translation.code = '78375-3', translation.codeSystem = '2.16.840.1.113883.6.1', translation.displayName = 'Discharge diagnosis Narrative';
  };
  section.title as title -> cdaSection.title as t, t.xmlText = title;
  section.text as text then {
    text.div as div -> cdaSection.text = div;
  };
  section.entry as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : AllergyIntolerance as allergy -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then AllergyToConcernAct(allergy, bundle, act);
      entry.resource : Condition as condition where (%section.code.coding.where(system = 'http://loinc.org' and code = '75310-3').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then ConditionToHealthConcernAct(condition, bundle, act);
      entry.resource : Condition as condition where (%section.code.coding.where(system = 'http://loinc.org' and code = '46241-6').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then ConditionToDiagnosisAct(condition, bundle, '2.16.840.1.113883.10.20.22.4.34', '46241-6', 'Hospital admission diagnosis', act);
      entry.resource : Condition as condition where (%section.code.coding.where(system = 'http://loinc.org' and code = '11535-2').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then ConditionToDiagnosisAct(condition, bundle, '2.16.840.1.113883.10.20.22.4.33', '11535-2', 'Hospital discharge diagnosis', act);
      entry.resource : Condition as condition where (%section.code.coding.where(system = 'http://loinc.org' and code in ('75310-3' | '46241-6' | '11535-2')).empty()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then ConditionToConcernAct(condition, bundle, act);
      // An admission medication: the Admission Medication act around the Medication Activity.
      entry.resource : MedicationRequest as request where (%section.code.coding.where(system = 'http://loinc.org' and code = '42346-7').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then {
        request -> act.classCode = 'ACT', act.moodCode = 'EVN';
        request -> act.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.36', template.extension = '2014-06-09';
        request -> act.code as code, code.code = '42346-7', code.codeSystem = '2.16.840.1.113883.6.1', code.displayName = 'Medications on admission';
        request -> act.statusCode as sc, sc.code = 'completed';
        request -> act.entryRelationship as relationship, relationship.typeCode = 'SUBJ', relationship.substanceAdministration as activity then MedicationRequestToActivity(request, bundle, activity);
      };
      entry.resource : MedicationRequest as request where (%section.code.coding.where(system = 'http://loinc.org' and code = '42346-7').empty() and category.coding.where(system = 'http://terminology.hl7.org/CodeSystem/medicationrequest-category' and code = 'discharge').empty()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.substanceAdministration as activity then MedicationRequestToActivity(request, bundle, activity);
      // A discharge medication: the Discharge Medication act around the Medication Activity.
      entry.resource : MedicationRequest as request where (%section.code.coding.where(system = 'http://loinc.org' and code = '42346-7').empty() and category.coding.where(system = 'http://terminology.hl7.org/CodeSystem/medicationrequest-category' and code = 'discharge').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then {
        request -> act.classCode = 'ACT', act.moodCode = 'EVN';
        request -> act.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.35', template.extension = '2016-03-01';
        request -> act.code as code, code.code = '10183-2', code.codeSystem = '2.16.840.1.113883.6.1', code.displayName = 'Hospital discharge medication', code.translation as translation, translation.code = '75311-1', translation.codeSystem = '2.16.840.1.113883.6.1', translation.displayName = 'Discharge medications';
        request -> act.statusCode as sc, sc.code = 'completed';
        request -> act.entryRelationship as relationship, relationship.typeCode = 'SUBJ', relationship.substanceAdministration as activity then MedicationRequestToActivity(request, bundle, activity);
      };
      entry.resource : Immunization as immunization -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.substanceAdministration as activity then ImmunizationToActivity(immunization, bundle, activity);
      entry.resource : DiagnosticReport as report -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.organizer as organizer then ReportToOrganizer(report, bundle, organizer);
      entry.resource : Observation as panel where (category.coding.where(code = 'vital-signs').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.organizer as organizer then PanelToOrganizer(panel, bundle, organizer);
      entry.resource : Procedure as procedure -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.procedure as cdaProcedure then ProcedureToCda(procedure, bundle, cdaProcedure);
      entry.resource : Observation as observation where (category.coding.where(code in ('vital-signs' | 'functional-status' | 'cognitive-status')).empty() and (%section.code.coding.where(system = 'http://loinc.org' and code = '29762-2').exists() or category.coding.where(code in ('social-history' | 'survey')).exists())) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.observation as cdaObservation then SocialToCda(observation, bundle, cdaObservation);
      entry.resource : Observation as observation where (category.coding.where(system = 'http://hl7.org/fhir/us/core/CodeSystem/us-core-category' and code = 'functional-status').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV' then StatusEntry(observation, bundle, 'functional', cdaEntry);
      entry.resource : Observation as observation where (category.coding.where(system = 'http://hl7.org/fhir/us/core/CodeSystem/us-core-category' and code = 'cognitive-status').exists()) -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV' then StatusEntry(observation, bundle, 'cognitive', cdaEntry);
      entry.resource : DocumentReference as note -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.act as act then DocumentReferenceToNote(note, bundle, act);
      entry.resource : Device as device -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.supply as supply then DeviceToSupply(device, bundle, supply);
      entry.resource : FamilyMemberHistory as member -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.organizer as organizer then FamilyMemberToOrganizer(member, bundle, organizer);
      entry.resource : Goal as goal -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.observation as observation then GoalToObservation(goal, bundle, observation);
      entry.resource : ServiceRequest as request -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.procedure as procedure then ServiceRequestToPlanned(request, bundle, procedure);
      entry.resource : Encounter as encounter -> cdaSection.entry as cdaEntry, cdaEntry.typeCode = 'DRIV', cdaEntry.encounter as cdaEncounter then EncounterToActivity(encounter, bundle, cdaEncounter);
    };
  };
  // The Social History section holds the Patient's birth sex, sex, gender identity and tribal
  // affiliation.
  section where (code.coding.where(system = 'http://loinc.org' and code = '29762-2').exists()) then {
    bundle.entry first as entry where (resource is Patient) then {
      entry.resource : Patient as patient then PatientToSocialEntries(patient, cdaSection);
    };
  };
  // A section whose template requires entries and that has none says so.
  section where (entry.empty() and code.coding.where(system = 'http://loinc.org' and code in ('48765-2' | '11450-4' | '75310-3' | '10160-0' | '11369-6' | '30954-2' | '8716-3' | '47519-4' | '46240-8' | '10183-2' | '61146-7')).exists()) -> cdaSection.nullFlavor = 'NI';
  section.section as nested -> cdaSection.component as component, component.section as cdaNested then Section(nested, bundle, cdaNested);
}
